import React, { useEffect, useState } from 'react';
import { Navigate } from 'react-router-dom';
import { Box, CircularProgress } from '@mui/material';
import ApiService from '../../services/api';
import { persistAdminPortalSession } from '../../utils/adminPortalSession';

interface AdminWriteRouteProps {
  children: React.ReactNode;
}

/** Restricts routes to platform administrators (not credentialed reviewers). */
const AdminWriteRoute: React.FC<AdminWriteRouteProps> = ({ children }) => {
  const [checking, setChecking] = useState(true);
  const [isAdminWrite, setIsAdminWrite] = useState(false);

  useEffect(() => {
    const check = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        setIsAdminWrite(false);
        setChecking(false);
        return;
      }
      try {
        const response = await ApiService.request('/auth/me');
        const user = response?.data?.user;
        const isAdmin = user?.role === 'admin';
        if (isAdmin && user) {
          persistAdminPortalSession(user, token);
        }
        setIsAdminWrite(isAdmin);
      } catch {
        setIsAdminWrite(false);
      } finally {
        setChecking(false);
      }
    };
    check();
  }, []);

  if (checking) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '40vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (!isAdminWrite) {
    return <Navigate to="/admin/dashboard" replace />;
  }

  return <>{children}</>;
};

export default AdminWriteRoute;
